#!/usr/bin/env bash
# The App Review demo account (docs/OPERATIONS.md → App Review demo account): creates
# or resets review@ryftlab.de and fills it with 60 days (scripts/seed_demo.py). The
# password goes into App Store Connect, never into the repo.
#
#   SUPABASE_URL=https://<ref>.supabase.co SUPABASE_ANON_KEY=sb_publishable_… SUPABASE_SECRET_KEY=sb_secret_… \
#   ADMIN_API_KEY=… DEMO_PASSWORD=… scripts/seed_demo.sh
#
# DEMO_PASSWORD comes from the environment only: its home was the in-cluster Vault (generated by
# the Vault root's Terraform), which went with D3 (D246), and nothing on GCP keeps it. App Store
# Connect → App Review Information holds the current one. ADMIN_API_KEY: scripts/lib/admin.sh says
# how to read production's.
set -euo pipefail
HERE=$(cd "$(dirname "$0")" && pwd)
: "${SUPABASE_URL:?set SUPABASE_URL}" "${SUPABASE_ANON_KEY:?set SUPABASE_ANON_KEY}"
: "${SUPABASE_SECRET_KEY:?set SUPABASE_SECRET_KEY (creates and resets the account)}"
: "${DEMO_PASSWORD:?set DEMO_PASSWORD (the password of the App Review account, as App Store Connect holds it; nothing in the repository or on GCP stores it)}"
export DEMO_PASSWORD
exec python3 "$HERE/seed_demo.py"
